window.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
window.until = async (fn, ms = 15000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (fn()) return true; await sleep(150) } return false };
window.nav = (name) => [...document.querySelectorAll('nav button')].find((b) => b.textContent.trim() === name).click();
window.chooseSelect = async (title, value) => { const el = [...document.querySelectorAll('select')].find((x) => x.title === title); if (!el) return 'NO SELECT ' + title; Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set.call(el, String(value)); el.dispatchEvent(new Event('change', { bubbles: true })); await sleep(1200); return title + ' = ' + (el.selectedOptions[0]?.textContent ?? el.value) };
window.setInput = (input, value) => { const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set; set.call(input, value); input.dispatchEvent(new Event('input', { bubbles: true })); input.dispatchEvent(new Event('change', { bubbles: true })) };
window.openPlayer = async (name) => { const input = document.querySelector('input[aria-label="Search players"]'); setInput(input, name); await until(() => [...document.querySelectorAll('aside button')].some((x) => x.textContent.includes(name))); const b = [...document.querySelectorAll('aside button')].find((x) => x.textContent.includes(name)); if (!b) return 'NOT LISTED ' + name; b.click(); await until(() => document.querySelector('h1')?.innerText.includes(name.split(' ').pop())); return 'opened ' + document.querySelector('h1')?.innerText.replace(/\n/g, ' ') };
window.openTeam = async (name) => { await until(() => [...document.querySelectorAll('button[role=row]')].some((x) => x.textContent.includes(name))); const b = [...document.querySelectorAll('button[role=row]')].find((x) => x.textContent.includes(name)); if (!b) return 'NOT LISTED ' + name; b.click(); await until(() => document.querySelector('h1')?.innerText.includes(name.split(' ').pop())); return 'opened ' + document.querySelector('h1')?.innerText.replace(/\n/g, ' ') };
window.tab = async (label) => { const t = [...document.querySelectorAll('[role=tab]')].find((x) => x.textContent.trim() === label); if (!t) return 'NO TAB ' + label; t.click(); await sleep(1500); return 'tab ' + label };
window.radio = async (group, label) => { const b = [...document.querySelectorAll('[role=radiogroup][aria-label="' + group + '"] [role=radio]')].find((x) => x.textContent.trim() === label); if (!b) return 'NO RADIO ' + group + '/' + label; b.click(); await sleep(1200); return group + ' = ' + label };
window.chart = (title = 'Shot chart') => { const s = document.querySelector('section[aria-label="' + title + '"]'); if (!s) return 'NO CHART'; const t = s.querySelector('[role=table][aria-label="Shots by zone"]'); const rows = t ? [...t.querySelectorAll('[role=row]')].slice(1).map((r) => [...r.querySelectorAll('[role=cell]')].map((c) => c.textContent.trim())) : []; return { total: Number(s.getAttribute('data-shot-total')), drawn: Number(s.getAttribute('data-shot-drawn')), head: s.querySelector('h2')?.parentElement?.innerText.replace(/\n/g, ' | '), status: s.querySelector('[role=status]')?.textContent ?? null, zones: rows } };
window.waitChart = async (title = 'Shot chart') => { await until(() => { const s = document.querySelector('section[aria-label="' + title + '"]'); return s && (s.hasAttribute('data-shot-total') || s.querySelector('[role=status]')) }); await sleep(400); return chart(title) };
window.check = (label, got, want) => (JSON.stringify(got) === JSON.stringify(want) ? 'PASS ' : 'FAIL ') + label + ' got ' + JSON.stringify(got) + ' want ' + JSON.stringify(want);
window.rail = (code) => { const b = [...document.querySelectorAll('[aria-label="The day’s games"] button')].find((x) => x.textContent.includes(code)); if (!b) return 'NOT ON THE RAIL ' + code; b.click(); return 'opened ' + b.innerText.replace(/\n/g, ' ') };
window.table = (label) => { const t = document.querySelector('[role=table][aria-label="' + label + '"]'); return t ? [...t.querySelectorAll('[role=row]')].slice(1).map((r) => [...r.querySelectorAll('[role=cell]')].map((c) => c.textContent.trim())) : null };
window.card = (id) => document.querySelector('[data-metric="' + id + '"]')?.innerText.replace(/\n/g, ' | ') ?? 'MISSING ' + id;
window.q = (metrics, scope, entity = 'player') => window.api.stats.query({ entity, metrics, scope });
window.val = (r, id, m) => r.rows.find((x) => x.id === id)?.values[m]?.value ?? null;
window.reason = (r, m) => r.columns.find((c) => c.id === m)?.reason ?? null;
window.boardHead = () => [...document.querySelectorAll('thead tr:last-child th')].map((c) => c.textContent.replace(/[▼▲]/g, '').trim());
window.boardRow = (name) => { const r = [...document.querySelectorAll('tbody tr')].find((x) => x.textContent.includes(name)); return r ? [...r.querySelectorAll('td')].map((c) => c.textContent.trim()) : null };
window.cell = (name, short) => { const h = boardHead(); const r = boardRow(name); if (!r) return 'NO ROW ' + name; const i = h.indexOf(short); return i < 0 ? 'NO HEAD ' + short : r[i + r.length - h.length] };
window.fix = (v, d = 1) => (v === null ? null : v.toFixed(d));
window.allSeasons = Array.from({ length: 34 }, (_, i) => 1994 + i);
